import pandas as pd

df = pd.read_csv('/app/data/restaurants/clean_restaurant_2022.csv')

def pick(city, cuisine):
    sub = df[df['City'].str.strip().str.lower()==city.lower()].copy()
    sub = sub[sub['Cuisines'].str.contains(cuisine, case=False, na=False)]
    return sub[['Name','Cuisines','Average Cost','Aggregate Rating']].head(5)

cities = ['Cleveland','Columbus','Cincinnati']
for city in cities:
    print('\n', city)
    for cuisine in ['American','Mediterranean','Chinese','Italian']:
        hits = pick(city, cuisine)
        print('\n', cuisine)
        print(hits.to_string(index=False) if not hits.empty else 'None')
